with filtered as (select *, round(datediff(start_date, end_date) / 30, 1) months_end_date_to_start_date from subscriptions where customer_id is not null) select dim.city, s.status, count(*) as cnt, min(s.monthly_fee) as min_monthly_fee, grouping_id() as gid from filtered s inner join customers dim on s.customer_id = dim.id group by grouping sets ((dim.city, s.status), (dim.city)) order by min_monthly_fee desc nulls first;
